   306	static UA_UInt16
   307	calculatePaddingAsym(const UA_SecurityPolicy *securityPolicy, const void *channelContext,
   308	                     size_t bytesToWrite, UA_Byte *paddingSize, UA_Byte *extraPaddingSize) {
   309	    size_t plainTextBlockSize = securityPolicy->asymmetricModule.cryptoModule.encryptionAlgorithm.
   310	        getRemotePlainTextBlockSize(securityPolicy, channelContext);
   311	    size_t signatureSize = securityPolicy->asymmetricModule.cryptoModule.signatureAlgorithm.
   312	        getLocalSignatureSize(securityPolicy, channelContext);
   313	    size_t paddingBytes = 1;
   314	    if(securityPolicy->asymmetricModule.cryptoModule.encryptionAlgorithm.
   315	        getRemoteKeyLength(securityPolicy, channelContext) > 2048)
   316	        ++paddingBytes;
   317	    size_t padding = (plainTextBlockSize - ((bytesToWrite + signatureSize + paddingBytes) %
   318	                                            plainTextBlockSize));
   319	    *paddingSize = (UA_Byte)(padding & 0xff);
   320	    *extraPaddingSize = (UA_Byte)(padding >> 8);
   321	    return (UA_UInt16)padding;
   322	}
